bounded_host_request.command:
set -euo pipefail
container="$(docker ps --format '{{.Names}}' | grep -E '(^|[-_])gaybbs([-_]|$)' | head -n1)"
test -n "$container" || exit 60
docker exec "$container" node --import /app/preload/telegram-ipv4-preload.mjs --input-type=module -e '
import fs from "node:fs";
const token=fs.readFileSync(process.env.BOT_TOKEN_FILE,"utf8").trim();
const recipient=Number(fs.readFileSync(process.env.GAYBBS_USERBOT_REPORT_CHAT_ID_FILE,"utf8").trim());
if(!token||!Number.isSafeInteger(recipient)||recipient<=0)process.exit(61);
const payload={chat_id:recipient,text:"🐞【運営通知テスト】不具合報告の配送経路確認（req_20261115062900a4c31b7458）"};
try{
 const response=await fetch("https://api.telegram.org/bot"+token+"/sendMessage",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload),signal:AbortSignal.timeout(20000)});
 const result=await response.json();
 if(!response.ok||result.ok!==true||!Number.isSafeInteger(result.result?.message_id))process.exit(62);
 console.log("USERBOT_REPORT_TEST_DELIVERED=PASS");
}catch{process.exit(63)}
' >/dev/null 2>&1 || exit 64
echo USERBOT_REPORT_TELEGRAM_API_DELIVERY=PASS
